import {BANK,CATEGORIES,ROOMS,FORMATS} from './questions.mjs';
import {ROUND_MS,HINT_MS,MATCH_LENGTH,buildDeck,pointsFor,isCorrect,normalize} from './engine.mjs';
import * as audio from './audio.mjs';

const $=s=>document.querySelector(s),main=$('#main'),dialog=$('#dialog');
const KEY='kikalmo-culture-demo-v2';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Math.round(n).toLocaleString('fr-FR');
const sec=ms=>(ms/1000).toFixed(1).replace('.',',');
const filters=['none','hue-rotate(40deg)','hue-rotate(150deg)','hue-rotate(230deg)','hue-rotate(305deg)'];
let storageOK=true,saveErrorShown=false;
function readStorage(){try{return JSON.parse(localStorage.getItem(KEY)||'null');}catch{storageOK=false;return null;}}
const stored=readStorage();
let profile={name:'Emmanuel',color:0,...stored?.profile},history=Array.isArray(stored?.history)?stored.history.slice(0,30):[],sound=stored?.sound??true;
if(typeof profile.name!=='string'||!profile.name.trim()||profile.name.length>20)profile.name='Emmanuel';
if(!Number.isInteger(profile.color)||!filters[profile.color])profile.color=0;
let session=validSession(stored?.session)?stored.session:null,view='lobby',ticker=null,toastTimer,pendingRoom=null,selectedColor=profile.color,audioPlaying=false,renderToken=0;
function validSession(s){return s&&Array.isArray(s.deck)&&s.deck.length===MATCH_LENGTH&&ROOMS.some(r=>r.id===s.roomId)&&Number.isInteger(s.index)&&s.index>=0&&s.index<MATCH_LENGTH&&s.deck.every(q=>q&&typeof q.id==='string'&&BANK.some(b=>b.id===q.id))&&Array.isArray(s.results)&&Number.isFinite(s.score)&&['playing','reveal','finished'].includes(s.phase);}
function save(){try{localStorage.setItem(KEY,JSON.stringify({profile,history,sound,session}));storageOK=true;}catch{storageOK=false;if(!saveErrorShown){saveErrorShown=true;toast('La sauvegarde locale est indisponible : garde cette page ouverte.');}}}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function announce(message){$('#announcer').textContent=message;}
function room(){return ROOMS.find(r=>r.id===session?.roomId);}
function current(){return session?.deck[session.index];}
function avatar(size='',color=profile.color){return `<svg class="puppet ${size}" viewBox="0 0 256 270" role="img" aria-label="Marionnette en laine Kikalmo" style="filter:${filters[color]||'none'}">
 <image href="assets/neck.webp" width="256" height="256" y="0"/>
 <image href="assets/outfit.webp" width="256" height="256" y="55"/>
 <svg width="256" height="256" viewBox="0 0 256 256" overflow="hidden"><image href="assets/head.webp" width="768" height="256"/></svg>
 <svg x="80" y="66" width="95" height="67" viewBox="85 67 93 66" overflow="hidden"><image href="assets/eyes.webp" width="1024" height="1536"/></svg>
 <svg x="87.5" y="149" width="82" height="41" viewBox="89 152 82 41" overflow="hidden"><image href="assets/mouth.webp" width="1024" height="1536"/></svg>
 <svg width="256" height="256" viewBox="0 0 256 256" overflow="hidden"><image href="assets/hair.webp" width="256" height="768"/></svg>
 </svg>`;}
function updateHeader(){ $('#profile').innerHTML=`${esc(profile.name)} <span>✎</span>`;$('#sound').textContent=sound?'♫':'♪';$('#sound').setAttribute('aria-label',sound?'Couper les effets sonores':'Activer les effets sonores');$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').title=sound?'Effets sonores activés':'Effets sonores coupés';}
function stopTicker(){clearInterval(ticker);ticker=null;}
function focusMain(){main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function bestScore(){return history.reduce((m,g)=>Math.max(m,g.score),0);}
function roomCard(r,featured=false){return featured?`<button class="featured paper" data-action="join" data-id="${r.id}" style="--accent:${r.color}"><span class="featured-symbol" aria-hidden="true">${r.icon}</span><div class="type-label">${esc(r.label)}</div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><span class="room-link"><span>Jouer · 10 questions</span><b aria-hidden="true">→</b></span></button>`:`<button class="theme-card paper" data-action="join" data-id="${r.id}" style="--accent:${r.color}"><span class="theme-symbol" aria-hidden="true">${r.icon}</span><span class="theme-copy"><strong>${esc(r.label)}</strong><small>${esc(r.title)}</small></span><span class="theme-arrow" aria-hidden="true">→</span></button>`;}
function showLobby(focus=true){view='lobby';document.body.classList.remove('game-view');stopTicker();audio.stop();audioPlaying=false;renderToken++;updateHeader();
 const recent=history.slice(0,3),active=session&&session.phase!=='finished';
 main.innerHTML=`<section class="lobby-heading"><div><span class="eyebrow">Un nouveau mode se tricote</span><h1>On joue à quoi ?</h1><p>Choisis ton salon. Les questions s’occupent du reste.</p></div><div class="rule-pills"><span>10 questions</span><span>25 s par question</span><span>La rapidité rapporte</span></div></section>
 ${active?`<div class="resume-banner"><div><b>Une partie t’attend</b><small>${esc(room()?.label)} · question ${session.index+1}/10 · ${num(session.score)} points</small></div><button class="primary" data-action="resume">Reprendre →</button></div>`:''}
 <div class="lobby-columns"><div><h2 class="section-label">Le général, à ta façon <small>Les thèmes se mélangent</small></h2><div class="featured-grid">${ROOMS.slice(0,3).map(r=>roomCard(r,true)).join('')}</div>
 <div class="theme-tools"><h2 class="section-label">Ou choisis un univers <small>Formats variés</small></h2><label class="search"><span class="sr-only">Chercher une catégorie</span><input id="room-search" type="search" placeholder="Chercher un thème…" autocomplete="off"></label></div><div id="themes" class="theme-grid">${ROOMS.slice(3).map(r=>roomCard(r)).join('')}</div></div>
 <aside class="lobby-side"><section class="side-card paper profile-card"><div class="mascot-stage">${avatar()}</div><p class="nickname">${esc(profile.name)}</p><small>À toi de tirer le bon fil.</small><div class="mini-stats"><div><b>${history.length}</b><small>parties dans ce navigateur</small></div><div><b>${num(bestScore())}</b><small>meilleur score</small></div></div><button class="text-button" data-action="profile">Modifier mon profil</button></section>
 <section class="side-card paper"><h2>Un peu de tout</h2><div class="format-list">${Object.entries(FORMATS).map(([k,[label,icon]])=>`<span>${icon} ${label.replace(' · 4 choix','')}</span>`).join('')}</div></section>
 <section class="side-card paper"><h2>Ton carnet</h2>${recent.length?`<ul class="recent">${recent.map(g=>`<li><span>${esc(ROOMS.find(r=>r.id===g.roomId)?.label||'Général')}<small>${g.correct}/10 · ${esc(new Date(g.at).toLocaleDateString('fr-FR',{day:'numeric',month:'short'}))}</small></span><b>${num(g.score)} pts</b></li>`).join('')}</ul>`:'<p>Une première partie et ton carnet prend vie.</p>'}<p>${storageOK?'Scores enregistrés sur cet appareil.':'Sauvegarde indisponible dans ce navigateur.'}</p></section></aside></div>`;
 if(focus)focusMain();
}
function openModal(content){dialog.innerHTML=content;dialog.showModal();document.body.classList.add('dialog-open');}
function closeModal(){dialog.close();document.body.classList.remove('dialog-open');pendingRoom=null;}
dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');pendingRoom=null;});
function showProfile(){selectedColor=profile.color;openModal(`<button class="dialog-close" data-action="close" aria-label="Fermer">×</button><h2 id="dialog-title">Ton petit personnage</h2><p>Un pseudo et une couleur pour cette démo.</p><form id="profile-form"><label for="nickname">Ton pseudo</label><input id="nickname" name="nickname" maxlength="20" required value="${esc(profile.name)}" autocomplete="nickname"><label>La couleur de ta laine</label><div class="avatar-colors" role="group" aria-label="Couleur du personnage">${['#e0c285','#b4c88c','#a7cac1','#b5a5ce','#dfadbb'].map((c,i)=>`<button type="button" data-action="color" data-id="${i}" style="--color:${c}" aria-label="${['Doré','Vert','Turquoise','Violet','Rose'][i]}" aria-pressed="${profile.color===i}"></button>`).join('')}</div><p id="profile-error" class="feedback" role="alert"></p><div class="dialog-actions"><button type="button" class="soft-button" data-action="close">Annuler</button><button class="primary" type="submit">Enregistrer</button></div></form>`);}
function showAbout(){openModal(`<button class="dialog-close" data-action="close" aria-label="Fermer">×</button><h2 id="dialog-title">Le futur mode culture</h2><p>Une démo solo habillée avec les véritables textures, le logo et les marionnettes de Kikalmo. Le nom du mode reste à choisir.</p><ul class="rules-list"><li>Un salon = une catégorie, ou une variante du général.</li><li>Chaque partie compte dix questions.</li><li>Une bonne réponse vaut de 1 000 à 100 points selon la rapidité.</li><li>Les QCM et vrai/faux acceptent un seul choix. Les réponses écrites peuvent être retentées pendant le chrono.</li><li>Les mélodies sont rejouées. Le chrono démarre à la première écoute.</li></ul><p>Plus tard : deux modes dans Kikalmo, avec un compte, une monnaie et une boutique communs. Cette démo ne crédite aucune monnaie et ne se connecte pas aux comptes du jeu.</p><p>Les scores et le profil sont conservés dans ce navigateur. Le multijoueur et les salons créés par les joueurs viendront lors de l’intégration.</p><div class="dialog-actions"><button class="primary" data-action="close">C’est parti</button></div>`);}
function confirmLeave(after){if(!session||session.phase==='finished'){after();return;}pendingRoom=after;openModal(`<h2 id="dialog-title">Quitter cette partie ?</h2><p>La partie en cours sera abandonnée. Tes parties déjà terminées restent dans ton carnet.</p><div class="dialog-actions"><button class="soft-button" data-action="close">Continuer la partie</button><button class="primary" data-action="confirm-leave">Quitter</button></div>`);}
function begin(roomId){const r=ROOMS.find(r=>r.id===roomId);if(!r)return;let deck;try{deck=buildDeck(BANK,r);}catch(e){toast(e.message);return;}
 session={id:crypto.randomUUID?.()||String(Date.now()),roomId,deck,index:0,score:0,results:[],phase:'playing',started:null,deadline:null,attempts:0,value:'',matchValues:[]};
 startQuestion();audio.unlock().catch(()=>{});}
function startQuestion(){audio.stop();audioPlaying=false;session.phase='playing';session.started=current().type==='audio'?null:Date.now();session.deadline=session.started===null?null:session.started+ROUND_MS;session.attempts=0;session.value='';session.matchValues=[];save();showGame();}
function remaining(){if(session?.phase!=='playing')return 0;return session.deadline===null?ROUND_MS:Math.max(0,session.deadline-Date.now());}
function elapsed(){return session.started===null?0:Math.max(0,Date.now()-session.started);}
function questionMedia(q,revealed=false){
 if(q.type==='rebus')return `<div class="puzzle-area"><div class="rebus-tiles">${q.tiles.map(([glyph,label],i)=>`${i?'<span class="rebus-plus" aria-hidden="true">+</span>':''}<span class="rebus-tile paper" role="img" aria-label="${esc(label)}"><span class="${glyph.length>3?'word':'glyph'}">${esc(glyph)}</span></span>`).join('')}</div></div>`;
 if(q.type==='emoji')return `<div class="puzzle-area"><div class="emoji-puzzle">${esc(q.visual)}</div></div>`;
 if(q.type==='audio')return `<div class="puzzle-area"><div class="audio-player paper"><div id="audio-wave" class="audio-wave" aria-hidden="true">${Array.from({length:23},(_,i)=>`<i style="--delay:-${i*.12}s"></i>`).join('')}</div><button class="primary" id="audio-play" data-action="play-audio" ${revealed?'disabled':''}>▶ ${session.started===null?'Écouter la mélodie':'Réécouter'}</button><p id="audio-status">${session.started===null?'Le chrono démarre à la première écoute.':'Mélodie rejouée · sans paroles'}</p></div></div>`;
 if(q.type==='order')return `<div class="puzzle-area"><ol class="order-list">${q.order.map((item,i)=>`<li><span>${i+1}</span><strong>${esc(item)}</strong><button data-action="move" data-index="${i}" data-dir="-1" aria-label="Monter ${esc(item)}" ${revealed||i===0?'disabled':''}>↑</button><button data-action="move" data-index="${i}" data-dir="1" aria-label="Descendre ${esc(item)}" ${revealed||i===q.order.length-1?'disabled':''}>↓</button></li>`).join('')}</ol></div>`;
 if(q.type==='match')return `<div class="puzzle-area"><div class="match-grid">${q.pairs.map(([left,right],i)=>`<div class="match-row"><label for="pair-${i}">${esc(left)}</label><span aria-hidden="true">→</span><select id="pair-${i}" data-pair="${i}" ${revealed?'disabled':''}><option value="">Choisir…</option>${q.right.map(v=>`<option value="${esc(v)}" ${session.matchValues[i]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('')}</div></div>`;
 if(q.type==='clue')return `<div class="puzzle-area"><ol class="clue-list" id="clue-list">${q.clues.map((c,i)=>`<li data-clue="${i}" class="${i&&!revealed?'locked':''}"><b>0${i+1}</b><span>${!i||revealed?esc(c):`Indice dans ${i*7} s`}</span></li>`).join('')}</ol></div>`;
 if(q.type==='image')return `<div class="puzzle-area"><div id="image-mystery" class="image-mystery ${revealed?'revealed':''}"><img src="${q.src}" alt="${revealed?esc(q.answer):'Un détail à reconnaître'}" width="100" height="100"></div></div>`;
 return '';
}
function answerControls(q,revealed){
 if(['qcm','tf','intruder'].includes(q.type)){const result=session.results[session.index];return `<div class="answers">${q.options.map((option,i)=>`<button class="choice paper ${revealed?(option===q.answer?'correct':option===result?.response?'wrong':''):''}" data-action="choice" data-index="${i}" ${revealed?'disabled':''}><b>${String.fromCharCode(65+i)}</b><span>${esc(option)}</span></button>`).join('')}</div>`;}
 if(['order','match'].includes(q.type))return `<div class="structured-submit"><button class="primary" data-action="structured" ${revealed?'disabled':''}>Valider ${q.type==='order'?'cet ordre':'les associations'} →</button></div>`;
 const estimate=q.type==='estimate';return `<form id="answer-form"><label class="answer-label" for="answer">${estimate?'Ton estimation':'Ta réponse'}</label><div class="${estimate?'estimate-unit':''}"><div class="answer-row"><input id="answer" name="answer" ${estimate?'type="text" inputmode="decimal"':'type="text" inputmode="text"'} maxlength="160" autocomplete="off" autocorrect="off" spellcheck="false" placeholder="${estimate?'Écris un nombre…':'Écris ta réponse…'}" value="${esc(session.value)}" ${revealed?'disabled':''}><button class="primary" type="submit" ${revealed?'disabled':''}>Valider <span aria-hidden="true">→</span></button></div>${estimate?`<span>${esc(q.unit)}</span>`:''}</div><p class="answer-meta">${estimate?`Tolérance : ${q.tolerance?`± ${num(q.tolerance)} ${esc(q.unit)}`:'réponse exacte'}.`:'Accents, espaces et ponctuation ne comptent pas.'}</p></form>`;
}
function showGame(focus=true){if(!session)return showLobby();if(session.phase==='finished')return showResults(focus);view='game';document.body.classList.add('game-view');stopTicker();const q=current(),r=room(),revealed=session.phase==='reveal';renderToken++;
 const result=session.results[session.index];
 main.innerHTML=`<div class="game-top"><div><button class="back-button" data-action="leave">← Les salons</button><h1>${esc(r.label)}</h1></div><div class="game-tools"><div class="score-chip"><img src="assets/star.webp" alt="" width="23" height="23"><span>${num(session.score)} pts</span></div><button class="soft-button" data-action="rules">Règles</button></div></div>
 <div class="game-layout"><article class="question-card paper"><div class="round-meta"><span class="format-tag"><span aria-hidden="true">${FORMATS[q.type][1]}</span>${FORMATS[q.type][0]}</span><span class="round-label">QUESTION ${session.index+1} / 10</span></div><div class="round-dots" aria-label="Question ${session.index+1} sur 10">${session.deck.map((x,i)=>`<span class="${i<session.index?(session.results[i]?.correct?'done':'wrong'):i===session.index?'current':''}"></span>`).join('')}</div>
 <div id="clock-line" class="clock-line"><div class="clock-track" role="progressbar" aria-label="Temps restant" aria-valuemin="0" aria-valuemax="25" aria-valuenow="25"><div id="clock-fill" class="clock-fill"></div></div><div class="clock-numbers"><strong id="clock-seconds">25<span style="font-size:12px"> s</span></strong><small id="clock-points">jusqu’à 1 000 pts</small></div></div>
 <p class="question-category">${esc(CATEGORIES.find(c=>c.id===q.category)?.label||'Culture générale')}</p><h2 class="question-title">${esc(q.prompt)}</h2>
 ${questionMedia(q,revealed)}${q.hint&&q.type!=='clue'?`<div id="hint" class="hint waiting">✦ Un indice après 10 secondes</div>`:''}${answerControls(q,revealed)}
 <p class="feedback" id="feedback" role="status"></p>
 ${revealed?`<section class="reveal paper ${result.correct?'':'failed'}" aria-live="polite"><div class="reveal-status">${result.correct?'✓ BIEN JOUÉ !':result.timedOut?'LE TEMPS EST ÉCOULÉ':result.skipped?'ON GARDE LE FIL':'LA BONNE RÉPONSE'}</div><h3>${esc(q.answer)}</h3><p>${esc(q.explain)}</p><div class="reveal-footer"><div class="gain">+${num(result.points)} pts<small>${result.correct?`Trouvé en ${sec(result.elapsed)} s`:'Une nouvelle chance à la prochaine question.'}</small></div><button class="primary" data-action="next">${session.index===9?'Voir mon résultat':'Question suivante'} →</button></div></section>`:`<div class="question-actions"><span class="answer-meta">${['qcm','tf','intruder'].includes(q.type)?'Un seul choix possible.':'Trouve avant la fin du chrono.'}</span><button class="skip-round" data-action="skip">Passer cette question</button></div>`}</article>
 <aside class="game-side"><section class="side-card paper"><div class="mascot-stage">${avatar()}</div><p class="nickname">${esc(profile.name)}</p><div class="player-score">${num(session.score)}</div><small>points dans cette partie</small><ul class="round-summary"><li><span>Bonnes réponses</span><strong>${session.results.filter(x=>x.correct).length} / 10</strong></li><li><span>Meilleur score local</span><strong>${num(bestScore())}</strong></li></ul></section><section class="side-card paper"><h2>Le plus vite, le mieux</h2><p>1 000 points au départ.<br>100 points juste avant la fin.<br>La bonne réponse arrête le chrono.</p><p>Démo solo · aucun joueur simulé.</p></section></aside></div>`;
 if(focus)focusMain();
 if(revealed){$('#clock-fill').style.width=`${Math.max(0,100*(1-result.elapsed/ROUND_MS))}%`;$('#clock-seconds').textContent=`${sec(result.elapsed)} s`;$('#clock-points').textContent=result.correct?'temps de réponse':'manche terminée';showHints(true);if(focus)$('[data-action="next"]')?.focus({preventScroll:true});}
 else {tick();if(session.phase==='playing'){ticker=setInterval(tick,100);if(focus&&q.type!=='audio')$('#answer')?.focus({preventScroll:true});}}
}
function showHints(all=false){const q=current();if(!q)return;const t=elapsed();if(q.type==='clue'){q.clues.forEach((c,i)=>{if(all||t>=i*7000){const li=$(`[data-clue="${i}"]`);if(li){li.classList.remove('locked');li.querySelector('span').textContent=c;}}});}
 const h=$('#hint');if(h&&(all||(session.started!==null&&t>=HINT_MS))){h.classList.remove('waiting');h.textContent='✦ '+q.hint;}
 if(q.type==='image'&&(all||t>=HINT_MS))$('#image-mystery')?.classList.add(all?'revealed':'hinted');
}
function tick(){if(view!=='game'||!session||session.phase!=='playing'){stopTicker();return;}const ms=remaining();
 if(session.deadline!==null&&ms<=0){finish(false,{timedOut:true,elapsed:ROUND_MS});return;}
 $('#clock-fill').style.width=`${100*ms/ROUND_MS}%`;$('#clock-seconds').innerHTML=`${(ms/1000).toFixed(0)}<span style="font-size:12px"> s</span>`;$('#clock-points').textContent=session.started===null?'à la première écoute':`${num(pointsFor(elapsed()))} pts possibles`;
 $('.clock-track')?.setAttribute('aria-valuenow',String(Math.ceil(ms/1000)));$('#clock-line').classList.toggle('urgent',ms<=5000);showHints();
}
function submit(value){if(!session||session.phase!=='playing')return;if(session.deadline!==null&&Date.now()>=session.deadline)return finish(false,{timedOut:true,elapsed:ROUND_MS});
 if(current().type==='audio'&&session.started===null){$('#feedback').textContent='Écoute d’abord la mélodie pour démarrer le chrono.';return;}
 if(typeof value==='string'&&!value.trim()){$('#feedback').textContent='Écris une réponse avant de valider.';$('#answer')?.focus();return;}
 if(current().type==='match'&&(!Array.isArray(value)||value.some(v=>!v))){$('#feedback').textContent='Choisis une réponse pour chacune des trois lignes.';return;}
 if(current().type==='estimate'&&!Number.isFinite(Number(String(value).replace(',','.')))){$('#feedback').textContent='Écris un nombre, sans ajouter l’unité.';return;}
 session.attempts++;session.value=typeof value==='string'?value:'';const good=isCorrect(current(),value);
 if(good||['qcm','intruder','tf'].includes(current().type))return finish(good,{response:value});
 $('#feedback').textContent='Pas encore… tu peux réessayer tant qu’il reste du temps.';if(sound)audio.cue(false);save();$('#answer')?.select();
}
function finish(correct,detail={}){if(!session||session.phase!=='playing')return;stopTicker();audio.stop();audioPlaying=false;const time=detail.elapsed??Math.min(ROUND_MS,elapsed()),points=correct?pointsFor(time):0;
 const result={questionId:current().id,correct:correct&&points>0,points,elapsed:time,response:detail.response??session.value,timedOut:!!detail.timedOut,skipped:!!detail.skipped,attempts:session.attempts};session.score+=points;session.results[session.index]=result;session.phase='reveal';save();if(sound)audio.cue(result.correct);showGame(false);$('[data-action="next"]')?.focus({preventScroll:true});announce(result.correct?`Bonne réponse. ${points} points.`:`La réponse était ${current().answer}.`);}
function next(){if(!session||session.phase!=='reveal')return;if(session.index===9){session.phase='finished';if(!history.some(g=>g.id===session.id)){history.unshift({id:session.id,at:Date.now(),roomId:session.roomId,score:session.score,correct:session.results.filter(r=>r.correct).length});history=history.slice(0,30);}save();showResults();}else{session.index++;startQuestion();}}
function showResults(focus=true){view='results';document.body.classList.remove('game-view');stopTicker();audio.stop();renderToken++;const r=room(),correct=session.results.filter(x=>x.correct),avg=correct.length?correct.reduce((s,x)=>s+x.elapsed,0)/correct.length:0;
 main.innerHTML=`<button class="back-button" data-action="home">← Les salons</button><section class="result-hero paper"><span class="eyebrow">${esc(r.label)} · partie terminée</span><div class="mascot-stage">${avatar()}</div><h1>${correct.length>=8?'Tu as tiré les bons fils !':correct.length>=5?'Bien joué, on garde le fil.':'Chaque question apprend quelque chose.'}</h1><div class="final-score">${num(session.score)} <small>/ 10 000 pts</small></div><div class="result-stats"><div><b>${correct.length}/10</b><span>bonnes réponses</span></div><div><b>${correct.length?sec(avg)+' s':'—'}</b><span>temps moyen des bonnes réponses</span></div><div><b>${num(bestScore())}</b><span>meilleur score local</span></div></div><div class="result-buttons"><button class="primary" data-action="replay">Rejouer dans ce salon →</button><button class="soft-button" data-action="home">Changer de salon</button></div></section><div class="history-title"><h2>Les dix fils de ta partie</h2><span class="eyebrow" style="margin:0">Les réponses et les explications</span></div><div class="review-list">${session.deck.map((q,i)=>{const result=session.results[i];return `<article class="review-item paper"><span class="review-icon ${result.correct?'':'failed'}">${result.correct?'✓':'·'}</span><div><strong>${i+1}. ${esc(q.prompt)}</strong><p>${esc(q.answer)}</p><small>${result.correct?`+${num(result.points)} points · ${sec(result.elapsed)} s`:result.skipped?'Question passée':result.timedOut?'Temps écoulé':'Réponse incorrecte'} · ${FORMATS[q.type][0]}</small><p class="review-explanation">${esc(q.explain)}</p></div></article>`;}).join('')}</div>`;if(focus)focusMain();announce(`Partie terminée. ${correct.length} bonnes réponses sur dix et ${session.score} points.`);}
async function playAudio(){if(!session||session.phase!=='playing'||current().type!=='audio')return;const id=session.id,index=session.index,token=renderToken;const button=$('#audio-play');button.disabled=true;button.textContent='Ouverture du son…';
 try{await audio.unlock();if(!session||session.id!==id||session.index!==index||session.phase!=='playing'||view!=='game'||renderToken!==token)return;
  if(session.started!==null&&remaining()<=0){finish(false,{timedOut:true,elapsed:ROUND_MS});return;}
  audio.playMelody(current().tune,()=>{audioPlaying=false;$('#audio-wave')?.classList.remove('playing');if($('#audio-play'))$('#audio-play').textContent='↻ Réécouter';});
  if(session.started===null){session.started=Date.now();session.deadline=session.started+ROUND_MS;save();}audioPlaying=true;$('#audio-wave')?.classList.add('playing');button.disabled=false;button.textContent='↻ Recommencer l’écoute';$('#audio-status').textContent='Mélodie rejouée · le chrono continue à chaque écoute';tick();
 }catch(e){button.disabled=false;button.textContent='▶ Réessayer la lecture';$('#feedback').textContent=e.message;}
}
function move(index,dir){if(!session||session.phase!=='playing'||current().type!=='order')return;if(remaining()<=0)return tick();const a=current().order,j=index+dir;if(j<0||j>=a.length)return;[a[index],a[j]]=[a[j],a[index]];save();showGame(false);$(`[data-action="move"][data-index="${j}"][data-dir="${dir}"]`)?.focus({preventScroll:true});}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
 if(action==='join'){const start=()=>begin(b.dataset.id);if(session&&session.phase!=='finished')confirmLeave(start);else start();}
 else if(action==='home'||action==='leave'){if(view==='game')confirmLeave(()=>showLobby());else showLobby();}
 else if(action==='resume'){if(!session)return;if(session.phase==='finished')showResults();else showGame();}
 else if(action==='choice')submit(current().options[Number(b.dataset.index)]);
 else if(action==='next')next();
 else if(action==='skip')finish(false,{skipped:true});
 else if(action==='structured')submit(current().type==='order'?current().order:session.matchValues.length===current().pairs.length?session.matchValues:Array.from({length:current().pairs.length},(_,i)=>session.matchValues[i]||''));
 else if(action==='move')move(Number(b.dataset.index),Number(b.dataset.dir));
 else if(action==='play-audio')playAudio();
 else if(action==='sound'){sound=!sound;save();updateHeader();if(sound)audio.unlock().catch(()=>{});toast(sound?'Effets sonores activés.':'Effets sonores coupés. Les mélodies restent disponibles.');}
 else if(action==='profile')showProfile();
 else if(action==='about')showAbout();
 else if(action==='rules'){openModal(`<button class="dialog-close" data-action="close" aria-label="Fermer">×</button><h2 id="dialog-title">Le bon fil, au bon moment</h2><ul class="rules-list"><li>10 questions, 25 secondes par question.</li><li>1 000 points au départ, puis le score diminue jusqu’à 100 points.</li><li>Une bonne réponse arrête le chrono.</li><li>Une seule tentative en QCM, intrus et vrai/faux.</li><li>Les autres formats permettent de réessayer.</li><li>Un indice apparaît après 10 secondes lorsqu’il est disponible.</li><li>Pour une mélodie, le chrono démarre à la première écoute.</li></ul><p>Le chrono de la question en cours continue pendant l’ouverture des règles.</p><div class="dialog-actions"><button class="primary" data-action="close">Revenir au jeu</button></div>`);}
 else if(action==='close')closeModal();
 else if(action==='confirm-leave'){const after=pendingRoom;closeModal();stopTicker();audio.stop();session=null;save();after?.();}
 else if(action==='color'){selectedColor=Number(b.dataset.id);dialog.querySelectorAll('[data-action="color"]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}
 else if(action==='replay')begin(session.roomId);
});
document.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();submit($('#answer').value);}if(e.target.id==='profile-form'){e.preventDefault();const name=$('#nickname').value.trim();if(!name||name.length>20){$('#profile-error').textContent='Choisis un pseudo de 1 à 20 caractères.';return;}profile={name,color:selectedColor};save();closeModal();updateHeader();if(view==='lobby')showLobby(false);else if(view==='game')showGame(false);else showResults(false);toast(storageOK?'Profil enregistré sur cet appareil.':'Le profil est actif pour cette session.');}});
document.addEventListener('input',e=>{if(e.target.id==='room-search'){const q=normalize(e.target.value),matches=ROOMS.slice(3).filter(r=>normalize(r.label+' '+r.title).includes(q));$('#themes').innerHTML=matches.length?matches.map(r=>roomCard(r)).join(''):'<p class="empty">Aucun salon pour cette recherche. Essaie un autre thème.</p>';}if(e.target.id==='answer'&&session){session.value=e.target.value;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-pair]')&&session){session.matchValues[Number(e.target.dataset.pair)]=e.target.value;save();}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||dialog.open||view!=='game'||session?.phase!=='playing')return;if(['qcm','intruder','tf'].includes(current().type)){const i='abcd'.indexOf(e.key.toLowerCase());if(i>=0&&current().options[i]){e.preventDefault();submit(current().options[i]);}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();audio.stop();audioPlaying=false;$('#audio-wave')?.classList.remove('playing');}else if(view==='game'&&session?.phase==='playing')tick();});
window.addEventListener('pagehide',save);
updateHeader();showLobby(false);
if(!storageOK)toast('La sauvegarde locale est indisponible dans ce navigateur.');
